import pandas as pd, numpy as np, json
df = pd.read_parquet('/beegfs2/scratch/rreider/genai4simpy/output/fischertechnik_lab_A/wandering-flying-bee/work_files/eventlog_cleaned.parquet')
st = df[df['lifecycle:transition']=='start'].copy()
st['dur_s'] = (pd.to_datetime(st['operation_end_time']) - pd.to_datetime(st['time:timestamp'])).dt.total_seconds()
comp = df[df['lifecycle:transition']=='complete'][['event_id','lifecycle:state']].rename(columns={'lifecycle:state':'state'})
m = st.merge(comp, on='event_id', how='left')
burn = m[(m['concept:name']=='/ov/burn') & (m['state']=='success')].copy()

def get_size(p):
    if not isinstance(p, dict): return None
    out = {}
    def walk(node):
        if isinstance(node, dict):
            if 'name' in node and 'value' in node and node['name']:
                out[node['name']] = node['value']
            for v in node.values(): walk(v)
        elif isinstance(node, (list, tuple)):
            for v in node: walk(v)
    walk(p)
    return out

burn['params'] = burn['parameters'].apply(get_size)
burn['size'] = burn['params'].apply(lambda d: d.get('parameter_burn_workpiece_size') or d.get('burn_workpiece_size'))
print(burn[['case','org:resource','dur_s','size']].to_string())
print('\nby size:')
print(burn.groupby('size')['dur_s'].agg(['count','mean','std','min','max']).to_string())

